'use strict';

// MODULES //

var hasProp = require( '@stdlib/assert/has-property' );
var isScaleName = require( '@stdlib/plot/vega/base/assert/is-scale-name' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var objectAssignIn = require( '@stdlib/object/assign-in' );
var join = require( '@stdlib/array/base/join' );
var ctors = require( '@stdlib/plot/vega/scale/ctors' );
var scaleNames = require( '@stdlib/plot/vega/scale/names' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns a function for creating a named scale.
*
* @param {string} type - scale type
* @param {string} name - default scale name
* @throws {TypeError} first argument must be a supported scale type
* @throws {TypeError} second argument must be a string
* @returns {Function} function for creating a named scale
*
* @example
* var xScale = factory( 'linear', 'xScale' );
*
* var scale = xScale();
* // returns <LinearScale>
*/
function factory( type, name ) {
	var defaults;
	var ctor;
	if ( !isScaleName( type ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be one of the following: "%s". Value: `%s`.', join( scaleNames(), ', ' ), type ) );
	}
	if ( !isString( name ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a string. Value: `%s`.', name ) );
	}
	ctor = ctors( type );
	defaults = {
		'name': name
	};
	return createScale;

	/**
	* Returns a named scale.
	*
	* @private
	* @param {Options} [options] - function options
	* @throws {TypeError} options argument must be an object
	* @throws {Error} must provide valid options
	* @returns {Scale} scale instance
	*/
	function createScale( options ) {
		var opts;
		if ( arguments.length ) {
			opts = objectAssignIn( {}, options );
			if ( !hasProp( opts, 'name' ) ) {
				opts.name = defaults.name;
			}
			return new ctor( opts );
		}
		return new ctor( defaults );
	}
}


// EXPORTS //

module.exports = factory;
